from fractions import Fraction as F

from sweep import Segment, find_intersections


def pts(*pairs):
    return sorted((F(x), F(y)) for x, y in pairs)


class TestTouching:
    def test_shared_upper_endpoint(self):
        assert find_intersections([(0, 0, 2, 2), (0, 0, 2, -2)]) == \
            pts((0, 0))

    def test_shared_lower_endpoint(self):
        assert find_intersections([(-3, -1, 0, 0), (3, -1, 0, 0)]) == \
            pts((0, 0))

    def test_lower_of_one_meets_upper_of_other(self):
        # Endpoint of b lands exactly on endpoint of a's interior point.
        assert find_intersections([(-4, 4, 4, -4), (1, -1, 6, 4)]) == \
            pts((1, -1))

    def test_endpoint_on_interior_tee(self):
        # a horizontal, b pierces a's interior at (1, 0) with an endpoint.
        assert find_intersections([(-2, 0, 3, 0), (1, -5, 1, 5)[:2] + ()
                                  ] if False else [(-2, 0, 3, 0), (-1, -2, 2, 4)]) == \
            pts((1, 0))  # b: y = 2x - 2 -> at x=1, y=0

    def test_crossing_at_start_point_of_both(self):
        assert find_intersections([(0, 0, 4, 2), (0, 0, 4, -2)]) == pts((0, 0))

    def test_crossing_where_cross_is_b_left_endpoint(self):
        a = Segment(0, 0, 4, 4)
        b = Segment(2, 2, 5, -1)
        assert find_intersections([a, b]) == pts((2, 2))

    def test_touch_plus_separate_crossing(self):
        # b touches a at (1,0); c crosses a at (2,0).
        segs = [(0, 0, 4, 0), (-1, -2, 2, 4), (2, -3, 2, 3)]
        segs[2] = None
        segs = [(0, 0, 4, 0), (-1, -2, 2, 4)]
        assert find_intersections(segs) == pts((1, 0))

    def test_chain_of_collinear_end_to_end(self):
        segs = [(0, 0, 2, 1), (2, 1, 4, 2)]
        assert find_intersections(segs) == pts((2, 1))

    def test_disjoint_segments_no_points(self):
        assert find_intersections([(0, 0, 1, 9), (5, 0, 6, 9)]) == []

    def test_many_events_same_point_pairwise_only(self):
        # X crossing plus a fourth segment ending on neither crossing.
        from sweep.geometry import segment_intersection
        a, b = Segment(-2, -2, 2, 2), Segment(-2, 2, 2, -2)
        c = Segment(10, 10, 11, 11)
        assert find_intersections([c, b, a]) == pts((0, 0))
